questionvariables.text:
/* Context: 1 = Green Valley admission numbers, 2 = Kenyan national ID numbers (merged from Relations Q9).
   Both are one-to-one, so the keyed option does not depend on ctx. */
ctx: rand([1, 2]);
/* Radio options: static literal values, sentence displays. Exactly one is true. */
ta1: [[optA, false, "A. One-to-many"], [optB, false, "B. Many-to-one"], [optC, true, "C. One-to-one"], [optD, false, "D. Many-to-many"]];
tac1: first(mcq_correct(ta1));
